/**
 * Provider logos for keys and the Property Inspector, using the official brand marks in
 * logos.mjs (generated by scripts/vendor-logos.mjs). Unknown providers get a monogram tile.
 */

import { FONT_STACK } from './colors.mjs';
import { LOGOS } from './logos.mjs';

const ALIASES = {
  anthropic: 'claude',
  chatgpt: 'codex',
  'gemini-cli': 'gemini',
  google: 'gemini',
  vertex: 'gemini',
  grok: 'xai',
  muse: 'meta',
  github: 'copilot',
  'github-copilot': 'copilot',
  moonshot: 'kimi',
};

function escapeXml(text) {
  return String(text ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

export function resolveLogoKey(provider) {
  const p = String(provider || '').toLowerCase();
  const key = ALIASES[p] || p;
  return LOGOS[key] ? key : null;
}

/**
 * Inner SVG markup on a 0..24 grid.
 * mono=false: the brand-coloured mark (single-colour marks are filled with `monoColor`).
 * mono=true: the single-colour mark filled with `monoColor`.
 */
function logoMarkup(provider, { mono = false, monoColor = '#ffffff', fallbackLabel = '' } = {}) {
  const key = resolveLogoKey(provider);
  if (key) {
    const logo = LOGOS[key];
    const rule = logo.evenodd ? ' fill-rule="evenodd"' : '';
    if (mono || logo.colorIsMono) {
      return `<g fill="${monoColor}"${rule}>${logo.mono}</g>`;
    }
    // Colour marks draw their neutral parts unfilled or in currentColor (e.g. Kimi's "K"),
    // which would be black-on-black; make both default to white on the key.
    return `<g fill="#ffffff" color="#ffffff">${logo.color}</g>`;
  }
  const ch = escapeXml(
    (fallbackLabel || provider || 'A').replace(/[^a-z0-9]/gi, '').slice(0, 1).toUpperCase() || 'A',
  );
  return `<rect x="1.5" y="1.5" width="21" height="21" rx="6" fill="${monoColor}"/>
    <text x="12" y="12.8" text-anchor="middle" dominant-baseline="central" font-family="${FONT_STACK}" font-size="14" font-weight="800" fill="#000000">${ch}</text>`;
}

/**
 * Renders a provider logo centred at (cx, cy), `size` units square.
 * `color` fills single-colour marks and the fallback tile; brand-coloured marks keep their own
 * colours unless `mono` is set (then the single-colour mark is filled with `color`).
 */
export function renderProviderIcon(provider, { cx, cy, size = 16, color = '#ffffff', fallbackLabel = '', mono = false } = {}) {
  const scale = size / 24;
  const tx = cx - size / 2;
  const ty = cy - size / 2;
  const glyph = logoMarkup(provider, { mono, monoColor: color, fallbackLabel });
  return `<g transform="translate(${tx.toFixed(2)} ${ty.toFixed(2)}) scale(${scale.toFixed(4)})">${glyph}</g>`;
}

/**
 * Standalone <svg> for the Property Inspector list.
 */
export function renderProviderIconSvg(provider, color = '#ffffff', size = 16, { mono = false } = {}) {
  const glyph = logoMarkup(provider, { mono, monoColor: color, fallbackLabel: provider });
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 24 24">${glyph}</svg>`;
}
